#include <linux/fs.h>
#include <linux/uaccess.h>
#include <linux/mutex.h>
#include <linux/wait.h>

ssize_t sound_timer_read(struct file *file, char __user *buffer, size_t count, loff_t *offset)
{
    struct sound_timer_dev *dev = file->private_data;
    ssize_t bytes_read = 0;
    int ret = 0;

    if (!dev || !buffer || count == 0) {
        return -EINVAL;
    }

    mutex_lock(&dev->mutex);
    spin_lock_irq(&dev->spinlock);

    while (dev->queue_head == dev->queue_tail) {
        if ((file->f_flags & O_NONBLOCK) || signal_pending(current)) {
            spin_unlock_irq(&dev->spinlock);
            mutex_unlock(&dev->mutex);
            return -EAGAIN;
        }

        wait_event_interruptible(dev->read_queue, dev->queue_head != dev->queue_tail);
    }

    while (bytes_read < count && dev->queue_head != dev->queue_tail) {
        char data = dev->queue[dev->queue_head++]; 
        dev->queue_head %= dev->queue_size;

        if (copy_to_user(buffer + bytes_read, &data, 1)) {
            ret = -EFAULT;
            break;
        }
        bytes_read++;
    }

    spin_unlock_irq(&dev->spinlock);
    mutex_unlock(&dev->mutex);

    if (ret < 0) {
        return ret;
    }

    return bytes_read;
}
